      "answer": "<b style=\"color:#16a34a;\">First-line</b>: Bisphosphonate<br>Second-line: denosumab<br>กรณีไม่สามารถใช้สองกลุ่มข้างบน ให้ใช้กลุ่มอื่นๆพิจารณาจากลักษณะทางคลินิก <br>(High risk)",
