      "track": "Clinic",
      "question": "tsDMARDS ใช้ตอนไหน",
      "questionImage": "",
      "answer": "💡 tsDMARDs ใช้เมื่อ csDMARDs ล้มเหลวหรือไม่ทนต่อ biologic",
      "answerImage": "",
