      "itemNo": "42",
      "group": "1. Musculoskeleton",
      "subTopic": "Rheumatoid arthritis",
      "track": "Clinic",
      "question": "bDMARDs ก่อนเริ่มใช้ต้องตรวจอะไร",
      "questionImage": "",
      "answer": "1. HIV\r<br>2. Tuberculosis (TB) → Tuberculin skin test หรือ IFN-γ release assay (IGRA)\r<br>3. Hepatitis B &amp; C\r<br>4. CBC, LFTs, Renal function<br><br>เพราะยากลุ่มนี้กดภูมิคุ้มกัน ทำให้ผู้ป่วยเสี่ยงติดเชื้อแฝง (latent infection) กลับมาเป็นซ้ำได้",
