      "question": "การไทเทรตกรดอ่อนด้วยเบสแก่ (weak acid + strong base) ที่จุด equivalence point จะมี pH เป็นอย่างไร และเพราะอะไร?",
      "questionImage": "",
      "answer": "pH &gt; 7 เพราะ conjugate base (A⁻) เป็น weak base ที่ hydrolyze กับน้ำได้ OH⁻ (เมื่อกรดอ่อนทำปฏิกิริยากับเบสแก่จนหมดพอดีที่ equivalence point สิ่งที่เหลืออยู่คือ A⁻ (conjugate base) ซึ่งเป็น weak base และเกิด A⁻ + H₂O ⇌ HA + OH⁻ ทำให้สารละลายเป็นเบส เช่นตัวอย่าง aspirin (pKa 3.5) ไทเทรตด้วย NaOH ในสไลด์ ที่ eq. point ได้ pH ≈ 8.73)",
      "answerImage": "",
      "note": ""
