      "question": "ลักษณะอาการสำคัญ",
      "questionImage": "",
      "answer": "Morning Stiffness มากกว่า 30 นาที (ุถ้า OA น้อยกว่า 30)<br>RA มัน Stiff หลังจากไม่ใช้งานนาน เช่น ตอนเช้าอนนหลับมา<br>Pain and tenderness<br>Swelling / Synovial hypertrophy<br>Warmth / Erythema<br>Deformity ( swan-neck, boutonnière, ulnar deviation)",
